<template><el-dialog title="账号模板" :visible.sync="visible" width="620px"><el-table :data="templates" size="small" empty-text="暂无模板"><el-table-column prop="templateName" label="模板名称"/><el-table-column label="字段"><template slot-scope="s">{{Object.keys(s.row.customFields||{}).join('、')||'无'}}</template></el-table-column><el-table-column label="首次完善" width="90"><template slot-scope="s">{{s.row.requireProfile?'是':'否'}}</template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="s"><el-button type="text" @click="use(s.row)">用此模板</el-button></template></el-table-column></el-table><el-divider/><el-form label-width="100px"><el-form-item label="模板名称"><el-input v-model.trim="form.templateName"/></el-form-item><el-form-item label="首次完善"><el-checkbox v-model="form.requireProfile">首次登录必须填写字段资料</el-checkbox></el-form-item><el-form-item label="字段"><div v-for="(f,i) in form.fields" :key="i" class="field-row"><el-input v-model.trim="f.key" placeholder="字段名"/><el-input v-model.trim="f.value" placeholder="默认值，可留空"/><el-button icon="el-icon-delete" circle @click="form.fields.splice(i,1)"/></div><el-button type="text" @click="form.fields.push({key:'',value:''})">添加字段</el-button></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">关闭</el-button><el-button type="primary" :loading="saving" @click="save">保存模板</el-button></span></el-dialog></template>
<script>import {listAccountTemplates,saveAccountTemplate} from '@/api/AccountManagement';export default{data:()=>({visible:false,saving:false,templates:[],form:{templateName:'',requireProfile:false,fields:[]}}),methods:{async open(){this.visible=true;this.templates=(await listAccountTemplates()).data||[]},fields(){const out={};this.form.fields.forEach(x=>{if(x.key)out[x.key]=x.value||''});return out},async save(){if(!this.form.templateName)return this.$message.warning('请输入模板名称');this.saving=true;try{await saveAccountTemplate({templateName:this.form.templateName,requireProfile:this.form.requireProfile,customFields:this.fields()});this.form={templateName:'',requireProfile:false,fields:[]};await this.open()}finally{this.saving=false}},use(row){this.$parent.editing=false;this.$parent.form={userId:null,userName:'',password:'',remark:'',slotId:'',enabled:true,requireProfile:row.requireProfile,customFields:Object.entries(row.customFields||{}).map(([key,value])=>({key,value}))};this.$parent.dialog=true;this.visible=false}}}</script>
<style scoped>.field-row{display:grid;grid-template-columns:1fr 1fr 36px;gap:8px;margin-bottom:8px}</style>
